import asyncio

async def profile():   # 정상
    await asyncio.sleep(0.05); return {"name": "김현대"}
async def search():    # 느려졌다
    await asyncio.sleep(5); return {"hits": []}
async def osb():       # 오류
    raise RuntimeError("dealer API 500")

FALLBACK = {"profile": None, "search": {"hits": [], "degraded": True},
            "osb": {"slots": [], "degraded": True}}

async def call(name, fn, timeout=0.3):
    try:
        return name, await asyncio.wait_for(fn(), timeout)
    except Exception as e:
        print(f"  {name}: {type(e).__name__} -> fallback")
        return name, FALLBACK[name]

async def feed():
    return dict(await asyncio.gather(
        call("profile", profile), call("search", search), call("osb", osb)))

loop = asyncio.new_event_loop(); t = loop.time()
print(loop.run_until_complete(feed())); print(f"elapsed {loop.time()-t:.2f}s")

# 출력
#   osb: RuntimeError -> fallback
#   search: TimeoutError -> fallback
# {'profile': {'name': '김현대'}, 'search': {'hits': [], 'degraded': True}, 'osb': {'slots': [], 'degraded': True}}
# elapsed 0.31s
